<template>
  <div ref="pageContainer" class="container">
    <div class="warper">
      <el-skeleton :loading="openLoading" animated>
        <template #template>
          <el-skeleton-item
            variant="text"
            style="
              width: 40%;
              height: 45px;
              margin-right: 60%;
              margin-top: 20px;
            "
          />
          <el-skeleton-item
            variant="text"
            style="width: 50%; height: 30px; margin-top: 20px"
          />
          <el-skeleton-item
            variant="text"
            style="width: 40%; height: 35px; margin-left: 40%; margin-top: 20px"
          />
          <el-skeleton-item
            variant="text"
            style="
              width: 80%;
              height: 240px;
              margin-right: 20%;
              margin-top: 20px;
            "
          />
        </template>
        <template #default>
          <div class="inner-container">
            <div class="header">
              <h1>{{ title }}</h1>
              <p v-if="messages.length > 0">
                {{ shareTime }} • 内容由 AI 生成，不能完全保障真实
              </p>
            </div>
            <RightClickMenu ref="rightClickMenu" :menu-items="menuItems">
              <div class="content-body">
                <div
                  v-for="(message, index) in messages"
                  :key="index"
                  class="message"
                >
                  <div
                    v-if="message.type === 'user'"
                    class="user-message"
                    @contextmenu.prevent="openMenu($event, message)"
                  >
                    <span>{{ message.content }}</span>
                    <div v-if="isMob" class="tools">
                      <el-tooltip
                        class="box-item"
                        effect="light"
                        content="复制"
                        placement="top"
                      >
                        <i
                          @click="copyContent($event, message.content)"
                          class="fa-solid fa-copy"
                        ></i>
                      </el-tooltip>
                    </div>
                  </div>
                  <div
                    class="markdown-body"
                    v-else
                    @contextmenu.prevent="openMenu($event, message)"
                  >
                    <div
                      class="inner"
                      v-html="markdwonToHTML(message.content, false)"
                    ></div>
                    <div v-if="isMob" class="tools">
                      <el-tooltip
                        class="box-item"
                        effect="light"
                        content="复制"
                        placement="top"
                      >
                        <i
                          @click="copyContent($event, message.content)"
                          class="fa-solid fa-copy"
                        ></i>
                      </el-tooltip>
                    </div>
                  </div>
                </div>
              </div>
            </RightClickMenu>
            <footer class="footer">
              <p class="beian">
                <a target="_blank" href="https://beian.miit.gov.cn">{{
                  config.BEI_AN_HAO
                }}</a>
              </p>
            </footer>
          </div>
        </template>
      </el-skeleton>
    </div>

    <div class="to-voa">
      <el-button @click="goHome" type="primary" :icon="ChatDotSquare" round
        >前往VoaTalk</el-button
      >
    </div>
  </div>
  <el-backtop :right="100" :bottom="100" />
  <el-drawer
    v-model="drawer"
    title="选取文本复制"
    :with-header="true"
    size="100%"
  >
    <span class="select-content">{{ selectContent }}</span>
  </el-drawer>
</template>

<script setup>
import { ref, onMounted, nextTick } from "vue";
import { useRoute } from "vue-router";
import { ElMessage } from "element-plus";
import "@/assets/css/github-markdown.css";
import "@/assets/css/hljs-github.css";
import "katex/dist/katex.min.css";
import { markdwonToHTML, addCopy, renderMermaid } from "@/utils/render-html";
import { ChatDotSquare } from "@element-plus/icons-vue";
import router from "@/router";
import { config } from "@/utils/config";

import { getRedisChat } from "@/api/aiChat";
import * as clipboard from "clipboard-polyfill";
import device from "current-device";
import RightClickMenu from "@/components/RightClickMenu";

const routePath = useRoute();
const messages = ref([]);
const title = ref(null);
const shareTime = ref(null);
const openLoading = ref(false);
const pageContainer = ref(null);
const isMob = ref(!device.mobile());
const rightClickMenu = ref(null);
const drawer = ref(false);
const selectContent = ref("");

function goHome() {
  router.replace("/home/chat");
}

const menuItems = ref([
  {
    icon: "fa-solid fa-copy",
    label: "复制内容",
    classList: [],
    action: (data) => {
      clipboard.writeText(data.content).then(
        () => {
          ElMessage.success("复制成功");
        },
        () => {
          ElMessage.error("链接复制失败");
          console.log("error!");
        }
      );
    },
  },
]);

if (!isMob.value) {
  menuItems.value.push({
    icon: "fa-regular fa-object-ungroup",
    label: "选取文字",
    classList: [],
    action: (data) => {
      selectContent.value = data.content;
      drawer.value = true;
    },
  });
}

function openMenu(event, message) {
  rightClickMenu.value && rightClickMenu.value.handleContextMenu(event, message);
}

function copyContent(event, content) {
  clipboard.writeText(content).then(
    () => {
      const oCopy = event.target;
      oCopy.className = "fas fa-check"; // 切换为成功图标
      oCopy.style.color = "#28a745"; // 成功颜色
      ElMessage.success("复制成功");

      setTimeout(() => {
        oCopy.className = "fa-solid fa-copy";
        oCopy.style.color = "rgb(117 116 116)"; // 恢复原样
      }, 1000); // 2 秒后恢复原样
    },
    () => {
      ElMessage.error("链接复制失败");
      console.log("error!");
    }
  );
}

onMounted(async function () {
  // console.log(routePath.params.id);
  openLoading.value = true;

  try {
    const obj = await getRedisChat({ r_id: routePath.params.id });
    // console.log(obj);
    messages.value = obj.data.talk_logs;
    title.value = obj.data.title;
    shareTime.value = obj.data.share_time;
    document.documentElement.querySelector("title").innerText =
      title.value || "VoaTalk 你的Ai助手";
  } catch (err) {
    console.log(err);
  }

  openLoading.value = false;

  nextTick(function () {
    renderMermaid();
    addCopy(pageContainer.value);
  });
});
</script>

<style scoped>
.container {
  width: 100%;
  display: flex;
  justify-content: center;
  overflow: auto;
  height: 100vh;
}

.warper {
  width: 43vw;
  padding: 80px 0;
}

.warper .inner-container {
  box-shadow: 0 6px 12px 0.5px var(--me-share-bg-color);
  border-radius: 24px;
  padding: 25px;
  box-sizing: border-box;
}

.el-skeleton {
  padding: 25px;
  width: 43vw;
}

.to-voa {
  position: fixed;
  top: 20px;
  right: 20px;
}

.warper .header h1 {
  font-size: 24px;
  font-weight: 600;
}

.warper .header p {
  font-size: 12px;
  color: var(--el-text-color-primary);
  border-bottom: 1px solid var(--el-text-color-primary);
  padding-bottom: 30px;
}

.markdown-body {
  padding: 10px;
  background-color: transparent;
}

.user-message {
  text-align: right;
  padding: 10px;
}

.user-message span {
  background: var(--me-bg-color);
  color: var(--el-text-color-primary);
  padding: 8px;
  border-radius: 8px;
  display: inline-flex;
  white-space: pre-wrap;
  max-width: 26vw;
  text-align: left;
  margin-bottom: 10px;
}

.message .tools {
  height: 30px;
  line-height: 30px;
  color: var(--el-text-color-regular);
  opacity: 0;
}

.tools i.fa-trash {
  color: rgb(255, 59, 48);
}

.tools i.fa-trash:hover {
  background: rgb(255, 59, 48, 0.1);
}

.message:hover .tools,
.message.active .tools {
  opacity: 1;
}

.markdown-body .tools i {
  margin-right: 5px;
}

.user-message .tools i {
  margin-left: 5px;
}

.user-message .tools i,
.markdown-body .tools i {
  padding: 6px;
  cursor: pointer;
}

.tools i:hover {
  padding: 6px;
  background: rgb(117, 116, 116, 0.1);
  border-radius: 4px;
}

.select-content {
  display: inline-flex;
  white-space: pre-wrap;
  text-align: left;
  -webkit-user-select: text;
  -moz-user-select: text;
  -ms-user-select: text;
  user-select: text;
}

@media (max-width: 1024px) {
  .warper {
    width: 70vw;
  }

  .warper .inner-container {
    padding: 15px;
  }

  .el-skeleton {
    width: 70vw;
  }

  .user-message span {
    max-width: 54vw;
  }
}

@media (max-width: 768px) {
  .warper {
    width: 95vw;
  }

  .content-body {
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }

  .warper .inner-container {
    padding: 15px;
  }

  .el-skeleton {
    width: 95vw;
  }

  .user-message span {
    max-width: 60vw;
  }
}

.beian {
  text-align: center;
  font-size: 14px;
}

.beian a {
  font-size: 14px;
  color: var(--me-report-text-color);
  text-decoration: none;
}
</style>